from typing import Optional as Opt
import os.path as osp
from .store import Store as S

class Base:
    def save(self):
        return self._write()
    def _write(self):
        return osp.join('a', 'b')

class User(Base):
    store: S
    def __init__(self, store: S):
        self.store = S()
        self.cache = dict()
    @property
    def name(self) -> Opt[str]:
        self.store.put('k')
        return self.save()

def make() -> User:
    u = User(S())
    u.name
    return Widget()

class Widget: pass

